55	// Write dispatches a persistent write request to the matching ref operation,
56	// mirroring the git-branch store's Write.
57	func (s *gitRefsStore) Write(ctx context.Context, req WriteRequest) error {
58		switch r := req.(type) {
59		case Session:
60			return s.writeSession(ctx, WriteOptions(r))
61		case SessionTranscript:
62			return s.backfillTranscript(ctx, UpdateOptions(r))
63		case SessionSummary:
64			return s.backfillSummary(ctx, r.CheckpointID, r.Summary)
65		case CheckpointAttribution:
