284	func (s *treeWriter) applySummaryBackfill(ctx context.Context, existing *object.Tree, basePath string, summary *Summary) (plumbing.Hash, string, error) {
285		entries, err := s.flattenExisting(existing, basePath)
286		if err != nil {
287			return plumbing.ZeroHash, "", err
288		}
289	
290		rootMetadataPath := checkpointSubtreePath(basePath, paths.MetadataFileName)
291		entry, exists := entries[rootMetadataPath]
292		if !exists {
293			return plumbing.ZeroHash, "", ErrCheckpointNotFound
294		}
295	
296		checkpointSummary, err := s.readSummaryFromBlob(entry.Hash)
297		if err != nil {
298			return plumbing.ZeroHash, "", fmt.Errorf("failed to read checkpoint summary: %w", err)
299		}
300	
301		// Find the latest session's metadata path (0-based indexing)
302		latestIndex := len(checkpointSummary.Sessions) - 1
303		sessionMetadataPath := checkpointSubtreePath(basePath, strconv.Itoa(latestIndex), paths.MetadataFileName)
304		sessionEntry, exists := entries[sessionMetadataPath]
305		if !exists {
306			return plumbing.ZeroHash, "", fmt.Errorf("session metadata not found at %s", sessionMetadataPath)
307		}
308	
309		existingMetadata, err := s.readMetadataFromBlob(sessionEntry.Hash)
310		if err != nil {
311			return plumbing.ZeroHash, "", fmt.Errorf("failed to read session metadata: %w", err)
312		}
313	
314		existingMetadata.Summary = RedactSummary(summary)
315	
316		metadataJSON, err := jsonutil.MarshalIndentWithNewline(existingMetadata, "", "  ")
317		if err != nil {
318			return plumbing.ZeroHash, "", fmt.Errorf("failed to marshal metadata: %w", err)
319		}
320		metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
321		if err != nil {
322			return plumbing.ZeroHash, "", fmt.Errorf("failed to create metadata blob: %w", err)
323		}
324		entries[sessionMetadataPath] = object.TreeEntry{
325			Name: sessionMetadataPath,
326			Mode: filemode.Regular,
327			Hash: metadataHash,
328		}

