220						if m := matchCheckpointPrefix(fresh, prefix); len(m) > 0 {
221							return m, fresh
222						}
223						_ = fresh.Close()
224					}
225				}
226			}
227			return nil, lookup
228		}
229	
230		stop := startSpinner(errW, "Fetching checkpoint metadata from remote")
231		_, v1Repo, v1Err := getMetadataTree(ctx)
